function resumoN1PilarHtml() {
  function selectField(key, label, choices) {
    var current = String(resumoPilar[key] || '');
    if (current && choices.indexOf(current) < 0) choices = choices.concat([current]);
    return '<label class="pillar-n1-summary-field"><span>' + label + '</span><select aria-label="' + label + '" data-sa-field="' + key + '">' + choices.map(function (value) {
      return '<option' + (value === current ? ' selected' : '') + '>' + textoSeguro(value) + '</option>';
    }).join('') + '</select></label>';
  }
  function numberField(key, label) {
    var value = resumoPilar[key];
    return '<label class="pillar-n1-summary-field"><span>' + label + '</span><input aria-label="' + label + '" data-sa-field="' + key + '" type="number" step="any"' + (key === 'pe_direito' ? ' min="0.01"' : '') + ' value="' + (Number.isFinite(Number(value)) && value !== null ? Number(value) : '') + '"></label>';
  }
  return '<section class="pillar-n1-summary"><strong>Campos SA / N1</strong><div>' +
    selectField('orientacao', 'Orientação', ['RETANGULAR VERTICAL', 'RETANGULAR HORIZONTAL', 'QUADRADO', 'ESPECIAL']) +
    selectField('classificacao', 'Classificação', ['SEGUE', 'MORRE', 'NASCE', 'INDETERMINADO']) +
    numberField('nivel_chegada', 'Nível de chegada') + numberField('nivel_saida', 'Nível de saída') +
    numberField('pe_direito', 'Altura do pé-direito (cm)') + '</div>' +
    '<button type="button" class="btn" data-sa-save>Salvar alterações dos campos SA</button> <span data-sa-status role="status"></span></section>';
}

