var saSave = fieldsPilar.querySelector('[data-sa-save]');
saSave.addEventListener('click', function () {
  var fields = {};
  fieldsPilar.querySelectorAll('[data-sa-field]').forEach(function (input) {
    var key = input.dataset.saField;
    if (String(input.value) !== String(resumoPilar[key])) fields[key] = input.value;
  });
  var statusSa = fieldsPilar.querySelector('[data-sa-status]');
  if (!Object.keys(fields).length) { statusSa.textContent = 'Nenhuma alteração.'; return; }
  saSave.disabled = true; statusSa.textContent = 'Salvando…';
  fetch('/obras/' + OBRA_ID + '/n1/' + encodeURIComponent(_painel3Estado.classe) + '/' + encodeURIComponent(itemId) + '/sa-review?pavimento=' + encodeURIComponent(_pavimentoSelecionado || item.pavimento), {
    method: 'PUT', credentials: 'same-origin', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({fields: fields})
  }).then(function (response) { return response.json().then(function (body) {
    if (!response.ok) throw new Error(body.detail || 'Falha ao salvar');
    if (window.DrillGrade) window.DrillGrade.refreshItems();
    carregarDetalheItemN1(itemId);
  }); }).catch(function (error) { saSave.disabled = false; statusSa.textContent = String(error.message || error); });
});
